import math
from collections import Counter


def knn(exemples, point, k):
    proches = sorted(exemples, key=lambda ex: math.dist(ex[0], point))[:k]
    return Counter(e for _, e in proches).most_common(1)[0][0]


def evaluer(exemples, k):
    app, test = separer(exemples, 0.25)
    justes = sum(1 for x, e in test if knn(app, x, k) == e)
    return round(justes / len(test), 2)
